def plot_fct_diff_ssird_vs_ideal(experiment_type, x_vals_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    fct_diff_s_list = [s - i for s, i in zip(ssird_fct_s_list, ideal_fct_s_list)]
    fct_diff_us_list = [x * pow(10,6) for x in fct_diff_s_list]

    plt.figure(figsize=(10, 6))
    plt.plot(x_vals_list, fct_diff_us_list, label="SSIRD - IDEAL", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)

    if experiment_type == VARY_BLOAD_SIZE:
        plt.xlabel('Byteload Size (B)')
        filename_prefix = "FCT_DIFF_VARY_BLOAD_SIZE_"
    elif experiment_type == VARY_INTERVAL:
        plt.xlabel('Inter-Byteload Interval (us)')
        filename_prefix = "FCT_DIFF_VARY_INTERVAL_"
    print(f"{filename_prefix:} FCT Diff (us): {fct_diff_us_list}")

    plt.ylabel('Flow Completion Time DIFF (us)')
    plt.title(f"FCT Diff: SSIRD vs Ideal: {experiment_type}\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()

def plot_fct_slowdown_ssird_vs_ideal(experiment_type, x_vals_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum="", is_log_x=False, is_log_y=False, y_lim=None):
    fct_slowdown_list = [s/i for s, i in zip(ssird_fct_s_list, ideal_fct_s_list)]

    plt.figure(figsize=(10, 6))
    plt.plot(x_vals_list, fct_slowdown_list, label="SSIRD/IDEAL", linestyle='-', marker='o', color=SSIRD_PLOT_COLOUR)

    if experiment_type == VARY_BLOAD_SIZE:
        plt.xlabel('Byteload Size (B)')
        filename_prefix = "FCT_SLOWDOWN_VARY_BLOAD_SIZE_"
    elif experiment_type == VARY_INTERVAL:
        plt.xlabel('Inter-Byteload Interval (us)')
        filename_prefix = "FCT_SLOWDOWN_VARY_INTERVAL_"
    print(f"{filename_prefix:} Slowdown: {fct_slowdown_list}")

    plt.ylabel('FCT Slowdown')
    plt.title(f"FCT Slowdown: SSIRD vs Ideal: {experiment_type}\n({num_flows} Flows; {flow_size_B}B per Flow; {total_gdpt_gbps}Gbps Total Goodput)\n {title_addendum}")
    plt.legend()
    plt.grid(True)
    if (is_log_x): plt.xscale('log')
    if (is_log_y): plt.yscale('log')
    if (y_lim): plt.ylim(y_lim)

    Path(PATH_TO_FCT_SLOWDOWN_PLOTS).mkdir(parents=True, exist_ok=True)
    filename = f"{filename_prefix}ssird_vs_ideal_{num_flows}flo_{flow_size_B}BperFlo_{total_gdpt_gbps}GbpsGdpt{title_addendum}.png"
    plt.savefig(f"{PATH_TO_FCT_SLOWDOWN_PLOTS}{filename}")
    plt.close()


def analyse_fct_slowdown_ssird_vs_ideal(inter_byteload_period_us_list, num_byteloads_list, byteload_size_B_list, ssird_fct_s_list_list, dctcp_fct_s_list_list, num_flows, flow_size_B, total_gdpt_gbps, rtt_s=RTT_5US_S, title_addendum=""):
    # NOTE: max 1 out of 15 flows is 93rd percentile 
    ssird_fct_s_max_list = [max(l) for l in ssird_fct_s_list_list]
    dctcp_fct_s_max_list = [max(l) for l in dctcp_fct_s_list_list]
    print(f"SSIRD FCT (s) MAX:{ssird_fct_s_max_list}")
    print(f"DCTCP FCT (s) MAX:{dctcp_fct_s_max_list}")

    # ssird_fct_s_mean_list = [statistics.mean(l) for l in ssird_fct_s_list_list]
    # dctcp_fct_s_mean_list = [statistics.mean(l) for l in dctcp_fct_s_list_list]
    # print(f"SSIRD FCT (s) MEAN:{ssird_fct_s_mean_list}")
    # print(f"DCTCP FCT (s) MEAN:{ideal_fct_s_mean_list}")

    theoretical_fct_parallel_flows_s_list = get_theoretical_fct_parallel_flows_s(num_flows, num_byteloads_list, byteload_size_B_list, inter_byteload_period_us_list, rtt_s)
    print(f"THEORETICAL IDEAL Exactly-parallel FCT (s):{theoretical_fct_parallel_flows_s_list}")

    ssird_fct_s_list = ssird_fct_s_max_list
    print("*** VS THEORY")
    ideal_fct_s_list = theoretical_fct_parallel_flows_s_list 
    # print("*** VS DCTCP")
    # ideal_fct_s_list = dctcp_fct_s_max_list 

    # Plot FCT
    plot_fct_vs_interval_ssird_vs_ideal(inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=None)
    plot_fct_vs_byteload_size_ssird_vs_ideal(byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=None)

    # Plot FCT Diff
    # fct_diff_ylim = (0, 2000)
    fct_diff_ylim = None
    plot_fct_diff_ssird_vs_ideal(VARY_INTERVAL, inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_diff_ylim)
    plot_fct_diff_ssird_vs_ideal(VARY_BLOAD_SIZE, byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_diff_ylim)

    # Plot FCT Slowdown
    # fct_slowdown_ylim = (0, 4)
    fct_slowdown_ylim = None
    plot_fct_slowdown_ssird_vs_ideal(VARY_INTERVAL, inter_byteload_period_us_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_slowdown_ylim)
    plot_fct_slowdown_ssird_vs_ideal(VARY_BLOAD_SIZE, byteload_size_B_list, ssird_fct_s_list, ideal_fct_s_list, num_flows, flow_size_B, total_gdpt_gbps, title_addendum, is_log_x=True, y_lim=fct_slowdown_ylim)

